    ZipEntry ze;
    while( zip.available() == 1 )
        if ( (ze = zip.getNextEntry()) != null
                && isClassFileName( ze.getName() ) )
            list.add( canonicalizeClassName( ze.getName() ) );
    zip.close();

    return list.toArray( new String[list.size()] );
}

